INSERT INTO races (
  id, name_ja, name_en, date, prefecture, city_ja, city_en,
  description_ja, description_en, official_url,
  entry_fee, entry_fee_by_category, entry_capacity,
  entry_start_date, entry_end_date, entry_closed,
  reception_type, reception_note_ja, reception_note_en,
  tags, course_gpx_file,
  course_max_elevation_m, course_min_elevation_m, course_elevation_diff_m,
  course_surface, course_certification,
  course_highlights_ja, course_highlights_en,
  course_notes_ja, course_notes_en,
  motif, motif_color, motif_romaji,
  tagline_ja, tagline_en,
  hero_image_url, hero_caption_ja, hero_caption_en,
  venue_name_ja, venue_name_en, venue_address, start_lat, start_lng,
  created_at, updated_at
) VALUES (
  'challenge-fuji5lakes-2027',
  'チャレンジ富士五湖ウルトラマラソン',
  'Challenge Fuji Five Lakes Ultra Marathon',
  '2027-04-18',
  '19',
  '富士吉田市',
  'Fujiyoshida City',
  '世界遺産・富士山と五つの湖を舞台にしたウルトラマラソン大会。62km・80km・100km・120kmの4種目から実力に合わせて選べる。フラットなコースと春の走りやすい気候で、初めてのウルトラマラソンにもおすすめ。120kmの部はSPARTATHLON一般エントリー枠の国際レース基準を満たす大会。',
  'An ultra marathon set against the World Heritage site of Mt. Fuji and five beautiful lakes. Choose from 4 distances: 62km, 80km, 100km, and 120km to match your ability. The flat course and pleasant spring climate make it ideal for first-time ultra marathon runners. The 120km category meets the international race criteria for SPARTATHLON general entry.',
  'https://www.r-wellness.com/fuji5/',
  19500,
  1,
  4700,
  '2026-10-30',
  '2027-01-31',
  0,
  'pre_mail',
  '大会当日の受付は行わない。ナンバーカード（ゼッケン）・計測タグ一式を事前に郵送。ただし海外居住者は前日受付を実施予定。',
  'No on-site reception on race day. Number cards and timing tags are mailed in advance. However, overseas residents will have pre-day reception.',
  '["SPARTATHLON基準","ウルトラマラソン","フラット","世界遺産","初ウルトラおすすめ","富士山","景色が良い"]',
  NULL,
  1050,
  830,
  220,
  'road',
  '[]',
  '河口湖畔の桜並木、西湖からの富士山眺望、精進湖、本栖湖（80km・120kmのみ）、山中湖（100km・120kmのみ）、富士北麓公園（スタート・フィニッシュ）',
  'Cherry blossom-lined Lake Kawaguchi shore, Mt. Fuji views from Lake Saiko, Lake Shoji, Lake Motosu (80km & 120km only), Lake Yamanaka (100km & 120km only), Fuji Hokuroku Park (start/finish)',
  '紙コップでの給水提供なし。携帯ボトル・カップ必須。補給食・防寒具・雨対策も携帯必須。標高830〜1050mのため、早朝は気温が低い（4月でも氷点下の可能性あり）。一般道路は歩道が無く車道が一車線の箇所が多いため、絶対に広がって走行しないこと。',
  'No paper cup water service. Carry your own bottle/cup. Must carry supplies, cold weather gear, and rain protection. Elevation 830-1050m, so early morning temperatures can be very low (below freezing possible even in April). Many sections of public roads have no sidewalk and only a single traffic lane, so runners must never spread out across the road.',
  '富士五湖',
  '#2563eb',
  'Fuji-Goko',
  '富士五湖を巡る、究極のチャレンジ',
  'The ultimate challenge around the five Fuji lakes',
  NULL,
  NULL,
  NULL,
  '富士北麓公園',
  'Fuji Hokuroku Park',
  '山梨県富士吉田市上吉田立石5000',
  35.426395,
  138.753159,
  '2026-10-24T13:22:35.944Z',
  '2026-11-08T15:17:59.883Z'
) ON CONFLICT(id) DO UPDATE SET
