INSERT OR REPLACE INTO access_points (race_id, station_name_ja, station_name_en, station_code, transport_to_venue_ja, transport_to_venue_en, latitude, longitude, walk_minutes, is_primary, sort_order) VALUES
  ('challenge-fuji5lakes-2027', '富士山駅', 'Fujisan Station', 'fujisan', '富士急行線富士山駅からタクシーで約15分', 'Approx. 15 min by taxi from Fujisan Station (Fujikyuko Line)', 35.4879, 138.7948, NULL, 1, 0);
INSERT OR REPLACE INTO access_points (race_id, station_name_ja, station_name_en, station_code, transport_to_venue_ja, transport_to_venue_en, latitude, longitude, walk_minutes, is_primary, sort_order) VALUES
  ('challenge-fuji5lakes-2027', '河口湖駅', 'Kawaguchiko Station', 'kawaguchiko', '河口湖駅からタクシーで約15分。大会当日のシャトルバスは富士山駅発。', 'Approx. 15 min by taxi from Kawaguchiko Station. Race day shuttle buses depart from Fujisan Station.', 35.4997, 138.7656, NULL, 0, 1);
INSERT OR REPLACE INTO nearby_spots (race_id, type, name_ja, name_en, description_ja, description_en, distance_from_venue, url, latitude, longitude) VALUES
  ('challenge-fuji5lakes-2027', '観光地', '富士山五合目', 'Mt. Fuji 5th Station', '標高約2,300mの富士山五合目。4月はまだ冬季閉鎖中の場合があるが、富士スバルラインからの富士山の眺望は圧巻。', 'Mt. Fuji 5th Station at approx. 2,300m altitude. May still be closed in April, but the views of Mt. Fuji from the Fuji Subaru Line are spectacular.', '富士北麓公園から車で約40分', NULL, 35.3606, 138.7274);
INSERT OR REPLACE INTO nearby_spots (race_id, type, name_ja, name_en, description_ja, description_en, distance_from_venue, url, latitude, longitude) VALUES
  ('challenge-fuji5lakes-2027', '温泉', '富士山溶岩の湯 泉水', 'Fuji Lava Hot Spring Sensui', '富士山の溶岩を使用した温泉施設。レース後のリカバリーに最適。富士山駅から徒歩圏内。', 'A hot spring facility using Mt. Fuji lava rocks. Perfect for post-race recovery. Within walking distance from Fujisan Station.', '富士山駅から徒歩約10分', NULL, 35.487, 138.79);
INSERT OR REPLACE INTO nearby_spots (race_id, type, name_ja, name_en, description_ja, description_en, distance_from_venue, url, latitude, longitude) VALUES
  ('challenge-fuji5lakes-2027', '温泉', '山中湖温泉 紅富士の湯', 'Yamanakako Onsen Beni Fuji no Yu', '山中湖畔にある日帰り温泉施設。露天風呂から富士山を一望できる。', 'A day-trip hot spring facility on the shore of Lake Yamanaka. Enjoy panoramic views of Mt. Fuji from the outdoor bath.', '富士北麓公園から車で約20分', NULL, 35.42, 138.86);
INSERT OR REPLACE INTO nearby_spots (race_id, type, name_ja, name_en, description_ja, description_en, distance_from_venue, url, latitude, longitude) VALUES
  ('challenge-fuji5lakes-2027', 'グルメ', '吉田のうどん', 'Yoshida Udon', '富士吉田市の名物料理。太くてコシの強い麺と味噌ベースのスープが特徴。市内に50軒以上のうどん店がある。レース後のエネルギー補給に最適。', 'A specialty dish of Fujiyoshida City. Characterized by thick, chewy noodles and miso-based soup. Over 50 udon shops in the city. Perfect for post-race energy replenishment.', '富士山駅周辺', NULL, 35.4879, 138.7948);
INSERT OR REPLACE INTO nearby_spots (race_id, type, name_ja, name_en, description_ja, description_en, distance_from_venue, url, latitude, longitude) VALUES
  ('challenge-fuji5lakes-2027', '観光地', '忍野八海', 'Oshino Hakkai', '富士山の伏流水が湧き出す8つの池からなる景勝地。世界遺産「富士山」の構成資産のひとつ。透明度の高い水面に映る富士山が美しい。', 'A scenic spot consisting of 8 ponds fed by Mt. Fuji''s underground water. Part of the World Heritage ''Mt. Fuji'' site. The clear water reflecting Mt. Fuji is breathtaking.', '富士北麓公園から車で約15分', NULL, 35.4578, 138.8306);
INSERT OR REPLACE INTO nearby_spots (race_id, type, name_ja, name_en, description_ja, description_en, distance_from_venue, url, latitude, longitude) VALUES
  ('challenge-fuji5lakes-2027', '観光地', '河口湖', 'Lake Kawaguchi', '富士五湖の中で最もアクセスが良い湖。4月は桜と富士山の共演が楽しめる。コース上でも湖畔を走る。', 'The most accessible of the Fuji Five Lakes. In April, enjoy cherry blossoms with Mt. Fuji. The course runs along the lakeshore.', '富士北麓公園から車で約10分', NULL, 35.51, 138.75);
INSERT OR REPLACE INTO participation_gifts (race_id, gift_categories, description_ja, description_en, image, sort_order) VALUES
  ('challenge-fuji5lakes-2027', '["tshirt","towel"]', '大会オリジナルTシャツ（THE NORTH FACE製）。2026年12月20日（日）までの申込者のうち先着2,800名（全種目合計）に贈呈。先着数到達後の申込者にはオリジナルタオルを贈呈。参加賞は「Tシャツ」または「タオル」のいずれか1点。2026年11月4日時点で予定数に達したため、Tシャツの受付は終了している。複数のエントリーサイトのデータを集約し、エントリー手続き完了時間を基準に申込順で判定するため、参加賞の確定連絡まで約1か月かかる。エントリー時にTシャツを選んでいてもタオルになる場合がある。', 'Official race T-shirt by THE NORTH FACE for the first 2,800 entrants (across all categories) who register by December 20, 2026 (Sun). Entrants after the limit is reached will receive an original towel instead. Participation gift is either the T-shirt or the towel, not both. As of November 4, 2026, the planned number has been reached and T-shirt allocation has closed. Because data from multiple entry sites is consolidated and judged in order of entry completion time, confirmation of the gift takes about one month. Even if you selected the T-shirt at entry, you may receive the towel.', NULL, 0);
